refentry.refsect1:
&reftitle.parameters;




   filename



     Il nome del file da controllare.

  &reftitle.examples;



    Esempio di is_uploaded_file


<?php

if (is_uploaded_file($_FILES['userfile']['tmp_name'])) {
   echo "File ". $_FILES['userfile']['name'] ." caricato correttamente.\n";
   echo "Visualizzazione del contenuto\n";
   readfile($_FILES['userfile']['tmp_name']);
} else {
   echo "Possibile attacco tramite upload di file: ";
   echo "nome del file '". $_FILES['userfile']['tmp_name'] . "'.";
}

?>
